+		t.Fatalf("block: want %v, got %v", want.Block, got.Block)
+	}
+	if want.Price.Cmp(got.Price) != 0 {
+		t.Fatalf("price: want %v, got %v", want.Price, got.Price)
+	}
+	if want.Total.Cmp(got.Total) != 0 {
