/** 
 * Run compaction and flushing memstore Assert deletes get cleaned up.
 * @throws Exception
 */
public void testCompaction() throws Exception {
  createStoreFile(r);
  for (int i=0; i < COMPACTION_THRESHOLD; i++) {
    createStoreFile(r);
  }
  addContent(new HRegionIncommon(r),Bytes.toString(COLUMN_FAMILY));
  Result result=r.get(new Get(STARTROW).addFamily(COLUMN_FAMILY_TEXT).setMaxVersions(100),null);
  assertEquals(COMPACTION_THRESHOLD,result.size());
  r.flushcache();
  r.compactStores();
  assertTrue(this.cluster.getFileSystem().exists(this.compactionDir));
  assertTrue(!this.cluster.getFileSystem().exists(this.regionCompactionDir));
  byte[] secondRowBytes=START_KEY.getBytes(HConstants.UTF8_ENCODING);
  secondRowBytes[START_KEY_BYTES.length - 1]++;
  result=r.get(new Get(secondRowBytes).addFamily(COLUMN_FAMILY_TEXT).setMaxVersions(100),null);
  assertEquals(3,result.size());
  Delete delete=new Delete(secondRowBytes,System.currentTimeMillis(),null);
  byte[][] famAndQf={COLUMN_FAMILY,null};
  delete.deleteFamily(famAndQf[0]);
  r.delete(delete,null,true);
  result=r.get(new Get(secondRowBytes).addFamily(COLUMN_FAMILY_TEXT).setMaxVersions(100),null);
  assertTrue(result.isEmpty());
  r.flushcache();
  result=r.get(new Get(secondRowBytes).addFamily(COLUMN_FAMILY_TEXT).setMaxVersions(100),null);
  assertTrue(result.isEmpty());
  createSmallerStoreFile(this.r);
  r.flushcache();
  result=r.get(new Get(secondRowBytes).addFamily(COLUMN_FAMILY_TEXT).setMaxVersions(100),null);
  assertTrue(result.isEmpty());
  r.compactStores(true);
  assertEquals(r.getStore(COLUMN_FAMILY_TEXT).getStorefiles().size(),1);
  result=r.get(new Get(secondRowBytes).addFamily(COLUMN_FAMILY_TEXT).setMaxVersions(100),null);
  assertTrue(result.isEmpty());
  int count=0;
  boolean containsStartRow=false;
  for (  StoreFile f : this.r.stores.get(COLUMN_FAMILY_TEXT).getStorefiles().values()) {
    HFileScanner scanner=f.getReader().getScanner(false,false);
    scanner.seekTo();
    do {
      byte[] row=scanner.getKeyValue().getRow();
      if (Bytes.equals(row,STARTROW)) {
        containsStartRow=true;
        count++;
      }
 else {
        assertFalse(Bytes.equals(row,secondRowBytes));
      }
    }
 while (scanner.next());
  }
  assertTrue(containsStartRow);
  assertTrue(count == 3);
  final int ttlInSeconds=1;
  for (  Store store : this.r.stores.values()) {
    store.ttl=ttlInSeconds * 1000;
  }
  Thread.sleep(ttlInSeconds * 1000);
  r.compactStores(true);
  count=count();
  assertTrue(count == 0);
}

/** 
 * In 2428, the meta region has just been set offline and then a close comes in.
 * @see <a href="https://issues.apache.org/jira/browse/HBASE-2428">HBASE-2428</a> 
 */
@Test(timeout=300000) public void testRegionCloseWhenNoMetaHBase2428() throws Exception {
  LOG.info("Running testRegionCloseWhenNoMetaHBase2428");
  MiniHBaseCluster cluster=TEST_UTIL.getHBaseCluster();
  final HMaster master=cluster.getMaster();
  int metaIndex=cluster.getServerWithMeta();
  int otherServerIndex=-1;
  for (int i=0; i < cluster.getRegionServerThreads().size(); i++) {
    if (i == metaIndex)     continue;
    otherServerIndex=i;
    break;
  }
  final HRegionServer otherServer=cluster.getRegionServer(otherServerIndex);
  final HRegionServer metaHRS=cluster.getRegionServer(metaIndex);
  final HRegionInfo hri=otherServer.getOnlineRegions().iterator().next().getRegionInfo();
  HBase2428Listener listener=new HBase2428Listener(cluster,metaHRS.getHServerInfo().getServerAddress(),hri,otherServerIndex);
  master.getRegionServerOperationQueue().registerRegionServerOperationListener(listener);
  try {
    cluster.abortRegionServer(metaIndex);
    while (!listener.metaShutdownReceived)     Threads.sleep(100);
    while (!listener.isDone())     Threads.sleep(10);
    assertTrue(listener.getCloseCount() > 1);
    assertTrue(listener.getCloseCount() < ((HBase2428Listener.SERVER_DURATION / HBase2428Listener.CLOSE_DURATION) * 2));
    assertRegionIsBackOnline(hri);
  }
  finally {
    master.getRegionServerOperationQueue().unregisterRegionServerOperationListener(listener);
  }
}

