  KeyValue kv22=new KeyValue(row1,fam1,qf2,ts2,KeyValue.Type.Put,null);
  KeyValue kv21=new KeyValue(row1,fam1,qf2,ts1,KeyValue.Type.Put,null);
  put=new Put(row1);
  put.add(kv13);
  put.add(kv12);
  put.add(kv11);
  put.add(kv23);
  put.add(kv22);
  put.add(kv21);
  region.put(put);
  List<KeyValue> expected=new ArrayList<KeyValue>();
  expected.add(kv13);
  expected.add(kv12);
